/**
 * Shim for `@deepseek-ai/cordis`.
 *
 * The real seam only uses `Service` as a base class whose constructor publishes
 * the instance on the context. Provider *selection* — the behaviour this test
 * exists to verify — never touches it, so a minimal base class is faithful
 * enough here and keeps the test free of the whole cordis framework.
 */
export class Service {
  constructor(ctx, name) {
    this.ctx = ctx
    this.name = name
    // The real Service calls `ctx.reflect.provide(name, this)`.
    ctx?.reflect?.provide?.(name, this)
  }
}

export default { Service }
